  me_s: [(m, v, r) => `E<sub>c</sub> = ½ · ${m} · ${v}² = <b>${r} J</b>`, (m, h, r) => `E<sub>p</sub> = ${m} · 9,8 · ${h} = <b>${r} J</b>`, (h, r, v2, exact) => `Se conserva la energía: arriba toda es potencial y abajo toda es cinética, m · g · h = ½ · m · v². La masa está en los dos lados y se tacha: ½ · v² = 9,8 · ${h}, es decir, v² = 2 · 9,8 · ${h} = ${v2}. Para quitar el cuadrado hacemos la raíz: v = √${v2} ${exact ? "=" : "≈"} <b>${r} m/s</b>`,
    (h1, h2, dh, half, v2, r, exact) => `Se conserva la energía mecánica: m · g · ${h1} = ½ · m · v² + m · g · ${h2}. La masa está en todos los términos y se tacha: ½ · v² = 9,8 · ${h1} − 9,8 · ${h2} = 9,8 · ${dh} = ${half}. Así, v² = 2 · ${half} = ${v2}. Para quitar el cuadrado hacemos la raíz: v = √${v2} ${exact ? "=" : "≈"} <b>${r} m/s</b>`,
    (v, hv, r, exact) => `Abajo toda la energía es cinética y arriba, potencial: ½ · m · ${v}² = m · 9,8 · h. La masa se tacha: ${hv} = 9,8 · h, y h = ${hv} / 9,8 ${exact ? "=" : "≈"} <b>${r} m</b>`],
  cl_q: [(m, sus, c, t1, t2) => `¿Qué energía (J) hace falta para calentar ${m} kg de ${sus} (c = ${c} J/(kg·°C)) de ${t1} °C a ${t2} °C?`, (m1, t1, m2, t2) => `Se mezclan ${m1} kg de agua a ${t1} °C con ${m2} kg de agua a ${t2} °C. ¿Cuál es la temperatura final (°C)?`],
  cl_s: [(m, c, d, r) => `Q = m · c · ΔT = ${m} · ${c} · ${d} = <b>${r} J</b>`, (m1, t1, m2, t2, r, exact) => `Llamamos t<sub>f</sub> a la temperatura final. Calor cedido = calor absorbido: ${m2} · 4180 · (${t2} − t<sub>f</sub>) = ${m1} · 4180 · (t<sub>f</sub> − ${t1}). Tachamos 4180 y quitamos los paréntesis: ${m2 * t2} − ${m2 === 1 ? "" : m2 + " "}t<sub>f</sub> = ${m1 === 1 ? "" : m1 + " "}t<sub>f</sub> − ${m1 * t1}. Pasamos las t<sub>f</sub> a un lado y los números al otro: ${m2 * t2} + ${m1 * t1} = ${m1 + m2} t<sub>f</sub>, es decir, ${m1 * t1 + m2 * t2} = ${m1 + m2} t<sub>f</sub>. Así, t<sub>f</sub> = ${m1 * t1 + m2 * t2} / ${m1 + m2} ${exact ? "=" : "≈"} <b>${r} °C</b>`],
